    proofPurpose: 'assertionMethod',
    verificationMethod: 'did:gxdid:179d197ff2a845d7b5bc5a5d3988b553#keys-1',
  },
}
// credentialSubject 下需要排除的字段（不做省略+复制处理）
const EXCLUDE_KEYS = ['id', 'verificationMethod']
// 视为 base64 的最小长度阈值（去掉前缀/padding 后），过短的不处理避免误判
const BASE64_MIN_LEN = 32

// 判断字符串是否为 base64 编码（兼容 data:xxx;base64, 前缀）
const isBase64 = (raw: string): boolean => {
  if (typeof raw !== 'string' || !raw) return false
  let str = raw
  // 去掉 data URI 前缀，如 data:application/pdf;base64,
  const idx = str.indexOf('base64,')
  if (idx >= 0) str = str.slice(idx + 'base64,'.length)
  // 去掉可能的两端引号
  str = str.replace(/^"|"$/g, '')
  // 去掉 padding
  const core = str.replace(/=+$/, '')
  if (core.length < BASE64_MIN_LEN) return false
  return /^[A-Za-z0-9+/]+$/.test(core) && core.length % 4 === 0
}

// 自定义值渲染：credentialSubject 下除 id / verificationMethod 外，base64 值省略 + 复制按钮
const customValueRender = (node: any, defaultRender: (n: any) => any) => {
  const fullKey: string = node?.key || ''
  const leafKey = fullKey.split('.').pop() || ''
  const value = node?.value

  const underCredentialSubject = fullKey === 'credentialSubject' || fullKey.startsWith('credentialSubject.')
  if (underCredentialSubject && !EXCLUDE_KEYS.includes(leafKey) && isBase64(value)) {
    const display = String(value).replace(/^"|"$/g, '')
    const max = 24
    const truncated = display.length > max ? display.slice(0, max) + '…' : display
    const onCopy = async () => {
      try {
        await navigator.clipboard.writeText(display)
        ElMessage.success('复制成功')
      } catch {
        ElMessage.error('复制失败')
      }
    }
    return (
      <span style="display:inline-flex;align-items:center;gap:4px;">
        <span class="jv-greed">{truncated}</span>
        <span onClick={onCopy} style="cursor:pointer;font-size:12px;color:#722ed1;padding:0 2px;" title="复制完整内容">
          复制
        </span>
      </span>
    )
  }
  return defaultRender(node)
}

